from pathlib import Path
import subprocess,resource,time,json,argparse,hashlib
p=argparse.ArgumentParser();p.add_argument('--executable',required=True);p.add_argument('--operator',required=True);p.add_argument('--mode',required=True);p.add_argument('--input',required=True);p.add_argument('--output',required=True);p.add_argument('--receipt',required=True);a=p.parse_args();start=time.monotonic();r=subprocess.run([a.executable,a.operator,a.mode,a.input,a.output],capture_output=True,text=True);elapsed=time.monotonic()-start;assert r.returncode==0,r.stderr
j={'mode':a.mode,'status':'PASS_ACTUAL_ACTION_EXECUTION','wall_seconds':elapsed,'peak_child_rss_kib':resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss,'stdout':r.stdout,'stderr':r.stderr,'output_sha256':hashlib.sha256(Path(a.output).read_bytes()).hexdigest(),'executable_sha256':hashlib.sha256(Path(a.executable).read_bytes()).hexdigest(),'scope':'Observed Linux reference runtime, not worst-case bound or full decoder benchmark'};Path(a.receipt).write_text(json.dumps(j,indent=2,sort_keys=True)+'\n');print(json.dumps({k:v for k,v in j.items()if k not in ['stderr','stdout']},indent=2))
